// Turns a Graph API lead (or a signed test lead) into the canonical inquiry shape.
const ev = $('Claim event').first().json;
const cfg = $('Config').first().json;
const payload = ev.payload || {};
const safe = (name) => {
  try { const it = $(name).first(); return it && it.json && !it.json.error ? it.json : null; } catch (e) { return null; }
};
let lead = null;
if (cfg.allow_test_leads && payload.test_lead) lead = payload.test_lead;
if (!lead) { const full = safe('Fetch lead'); if (full && Array.isArray(full.field_data)) lead = full; }
if (!lead) { const basic = safe('Fetch lead (basic fields)'); if (basic && Array.isArray(basic.field_data)) lead = basic; }
if (!lead) throw new Error('Could not load lead ' + payload.leadgen_id + ' from the Graph API');
const form = (payload.test_lead && payload.test_lead.form) || safe('Fetch form') || {};

const KNOWN = {
  full_name: 'full_name', name: 'full_name', first_name: 'first_name', last_name: 'last_name',
  email: 'email', work_email: 'email', phone_number: 'phone', phone: 'phone', mobile: 'phone',
  mobile_number: 'phone', whatsapp_number: 'phone', preferred_language: 'language', language: 'language',
};
const label = (k) => k.replace(/[_?]+/g, ' ').trim().replace(/^\w/, (c) => c.toUpperCase());
const f = {};
const answers = {};
for (const item of lead.field_data || []) {
  const key = String(item.name || '').trim();
  const vals = Array.isArray(item.values) ? item.values : [item.values];
  const val = vals.filter((v) => v !== null && v !== undefined && String(v).trim() !== '').join(', ');
  const canon = KNOWN[key.toLowerCase()];
  if (canon && !f[canon]) f[canon] = val;
  else if (val) answers[label(key)] = val.slice(0, 500);
}
const isoTime = (t) => {
  if (t === null || t === undefined || t === '') return null;
  const d = /^\d+$/.test(String(t)) ? new Date(Number(t) * 1000)
    : new Date(String(t).replace(/([+-]\d{2})(\d{2})$/, '$1:$2'));
  return isNaN(d.getTime()) ? null : d.toISOString();
};
const organic = lead.is_organic === true || lead.is_organic === 'true';
return [{ json: {
  inbox_id: ev.inbox_id,
  channel: 'meta',
  submitted_at: isoTime(lead.created_time) || isoTime(payload.created_time) || new Date().toISOString(),
  full_name: f.full_name || null, first_name: f.first_name || null, last_name: f.last_name || null,
  phone_raw: f.phone || null, email_raw: f.email || null, language_hint: f.language || null,
  form_locale: form.locale || null,
  source_detail: 'Meta lead form: ' + (form.name || lead.form_id || payload.form_id || 'unknown'),
  campaign_id: lead.campaign_id || null,
  campaign_name: lead.campaign_name || (organic ? 'Organic (lead form)' : null),
  adset_name: lead.adset_name || null,
  ad_name: lead.ad_name || null,
  form_id: String(lead.form_id || payload.form_id || '') || null,
  form_name: form.name || null,
  platform: lead.platform || null,
  is_organic: organic,
  answers,
  message: null,
  is_test: !!payload.test_lead,
} }];

// Maps any website form (custom HTML, WordPress plugins, Webflow...) to the canonical shape.
const ev = $('Claim event').first().json;
const p = ev.payload || {};
const src = p.fields || {};
const meta = p.meta || {};
const used = new Set(['submission_id', 'submissionId', '_sid', 'form_started_at', '_ts']);
const get = (...keys) => {
  keys.forEach((k) => used.add(k));
  for (const k of keys) { const v = src[k]; if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim(); }
  return null;
};
const full = get('name', 'full_name', 'fullname', 'parent_name', 'your-name');
const first = get('first_name', 'firstname', 'fname');
const last = get('last_name', 'lastname', 'lname', 'surname');
const phone = get('phone', 'mobile', 'phone_number', 'tel', 'telephone', 'whatsapp', 'your-phone', 'contact_number');
const email = get('email', 'email_address', 'your-email', 'mail');
const message = get('message', 'comments', 'comment', 'your-message', 'notes', 'enquiry', 'inquiry', 'question');
const lang = get('language', 'lang', 'preferred_language', 'locale');
const utm = {
  source: get('utm_source'), medium: get('utm_medium'), campaign: get('utm_campaign'),
  content: get('utm_content'), term: get('utm_term'),
};
const gclid = get('gclid');
const fbclid = get('fbclid');
const pageUrl = get('page_url', 'page', 'url', 'source_url', 'landing_page') || meta.referer || null;
const referrer = get('referrer', 'referer');
const formName = get('form_name', 'form', 'form_id', 'formName');
const label = (k) => k.replace(/[_-]+/g, ' ').trim().replace(/^\w/, (c) => c.toUpperCase());
const answers = {};
for (const [k, v] of Object.entries(src)) {
  if (used.has(k) || v === null || v === undefined) continue;
  const val = Array.isArray(v) ? v.join(', ') : (typeof v === 'object' ? JSON.stringify(v) : String(v));
  if (val.trim()) answers[label(k)] = val.trim().slice(0, 500);
}
const campaign = utm.campaign
  || (utm.source ? [utm.source, utm.medium].filter(Boolean).join(' / ')
  : (gclid ? 'google / cpc (gclid)' : (fbclid ? 'facebook / referral (fbclid)' : 'Website (direct)')));
return [{ json: {
  inbox_id: ev.inbox_id,
  channel: 'web',
  submitted_at: meta.received_at || new Date().toISOString(),
  full_name: full, first_name: first, last_name: last,
  phone_raw: phone, email_raw: email, language_hint: lang, form_locale: null,
  source_detail: 'Website form' + (formName ? ': ' + formName : '')
    + (pageUrl ? ' (' + String(pageUrl).replace(/^https?:\/\//, '').slice(0, 80) + ')' : ''),
  campaign_id: null, campaign_name: campaign, adset_name: null, ad_name: null,
  form_id: formName, form_name: formName, platform: 'web',
  is_organic: !utm.source && !gclid && !fbclid,
  utm_source: utm.source, utm_medium: utm.medium, utm_campaign: utm.campaign,
  utm_content: utm.content, utm_term: utm.term, gclid, fbclid, page_url: pageUrl, referrer,
  answers, message, is_test: /^(test|leadops-test)/i.test(String(src.submission_id || '')),
} }];

// Phone -> E.164, email -> lowercase, names split, language detected.
// Handles Arabic-Indic digits (٠-٩ / ۰-۹) and local formats like 050 123 4567.
const cfg = $('Config').first().json;
const cc = String(cfg.default_country_code || '971').replace(/\D/g, '');
const c = $input.first().json;
const ascii = (s) => String(s === null || s === undefined ? '' : s)
  .replace(/[\u0660-\u0669]/g, (d) => String(d.charCodeAt(0) - 0x0660))
  .replace(/[\u06F0-\u06F9]/g, (d) => String(d.charCodeAt(0) - 0x06F0));
function phoneE164(raw) {
  const s = ascii(raw).trim();
  if (!s) return null;
  const plus = s.startsWith('+');
  let d = s.replace(/\D/g, '');
  if (!d) return null;
  if (!plus) {
    if (d.startsWith('00')) d = d.slice(2);                 // 00971...
    else if (d.startsWith('0')) d = cc + d.slice(1);        // 050... -> 97150...
    else if (d.length <= 9) d = cc + d;                     // 501234567 or 8-digit local numbers
  }
  if (d.startsWith(cc + '0')) d = cc + d.slice(cc.length + 1);   // +971 (0) 50...
  return d.length >= 8 && d.length <= 15 ? '+' + d : null;
}
function cleanEmail(raw) {
  const e = String(raw || '').trim().toLowerCase().replace(/^mailto:/, '');
  return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(e) ? e : null;
}
const tidy = (s) => { const t = String(s || '').replace(/\s+/g, ' ').trim(); return t || null; };
let first = tidy(c.first_name);
let last = tidy(c.last_name);
let full = tidy(c.full_name);
if (!full && (first || last)) full = [first, last].filter(Boolean).join(' ');
if (full && !first && !last) { const parts = full.split(' '); first = parts[0]; last = parts.slice(1).join(' ') || null; }
const langOf = (v) => {
  const s = String(v || '').trim().toLowerCase();
  if (!s) return null;
  if (/^ar$|^ar[_-]|arab|عرب/.test(s)) return 'ar';
  if (/^en$|^en[_-]|engl|انجل|إنجل/.test(s)) return 'en';
  if (/^fr$|^fr[_-]|fren|fran/.test(s)) return 'fr';
  if (/^ur$|^ur[_-]|urdu/.test(s)) return 'ur';
  if (/^hi$|^hi[_-]|hindi/.test(s)) return 'hi';
  return null;
};
const arabicScript = /[\u0600-\u06FF]/.test([full, c.message, ...Object.values(c.answers || {})].join(' '));
const language = langOf(c.language_hint) || langOf(c.form_locale) || (arabicScript ? 'ar' : 'en');
const phone = phoneE164(c.phone_raw);
const email = cleanEmail(c.email_raw);
if (!phone && !email) {
  throw new Error(`Inquiry from inbox ${c.inbox_id} has no usable phone or email `
    + `(phone="${c.phone_raw || ''}", email="${c.email_raw || ''}")`);
}
return [{ json: { ...c, full_name: full, first_name: first, last_name: last, phone_e164: phone, email, language } }];

