WITH i AS (
  UPDATE leadops.inquiries SET crm_synced_at = now(), crm_record_id = $2::text
   WHERE id = $1::bigint RETURNING lead_id
), l AS (
  UPDATE leadops.leads SET crm_record_id = coalesce(crm_record_id, $2::text), updated_at = now()
   WHERE id = (SELECT lead_id FROM i) RETURNING id
)
INSERT INTO leadops.events (inquiry_id, lead_id, type, detail)
SELECT $1::bigint, (SELECT id FROM l), 'crm_synced', jsonb_build_object('record_id', $2::text, 'action', $3::text)
RETURNING inquiry_id;
